using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetShipmentsAsync(string? statusFilter = null)
    {
        await SeedIfEmptyAsync();

        IQueryable<ShipmentEntity> query = db.Shipments;

        if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, true, out var status))
        {
            query = query.Where(s => s.Status == (int)status);
        }

        return await query.Select(e => MapToModel(e)).ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        await SeedIfEmptyAsync();

        var entity = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : MapToModel(entity);
    }

    public async Task<Shipment?> GetShipmentByIdAsync(int id)
    {
        var entity = await db.Shipments.FindAsync(id);
        return entity is null ? null : MapToModel(entity);
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is not null)
        {
            entity.Status = (int)status;
            await db.SaveChangesAsync();
        }
    }

    private static Shipment MapToModel(ShipmentEntity e) => new()
    {
        Id = e.Id,
        TrackingNumber = e.TrackingNumber,
        Origin = e.Origin,
        Destination = e.Destination,
        Status = (ShipmentStatus)e.Status,
        ShippedDate = e.ShippedDate,
        EstimatedDelivery = e.EstimatedDelivery,
        RecipientName = e.RecipientName,
        Description = e.Description
    };

    private async Task SeedIfEmptyAsync()
    {
        if (await db.Shipments.AnyAsync())
            return;

        var now = DateTime.UtcNow;
        db.Shipments.AddRange(
            new ShipmentEntity
            {
                TrackingNumber = "TRK-1001",
                Origin = "New York, NY",
                Destination = "Los Angeles, CA",
                Status = (int)ShipmentStatus.InTransit,
                ShippedDate = now.AddDays(-3),
                EstimatedDelivery = now.AddDays(2),
                RecipientName = "Alice Johnson",
                Description = "Electronics – 2 boxes"
            },
            new ShipmentEntity
            {
                TrackingNumber = "TRK-1002",
                Origin = "Chicago, IL",
                Destination = "Houston, TX",
                Status = (int)ShipmentStatus.Pending,
                ShippedDate = now.AddDays(-1),
                EstimatedDelivery = now.AddDays(4),
                RecipientName = "Bob Smith",
                Description = "Furniture – 1 pallet"
            },
            new ShipmentEntity
            {
                TrackingNumber = "TRK-1003",
                Origin = "Seattle, WA",
                Destination = "Denver, CO",
                Status = (int)ShipmentStatus.Delivered,
                ShippedDate = now.AddDays(-7),
                EstimatedDelivery = now.AddDays(-2),
                RecipientName = "Carol White",
                Description = "Books – 3 packages"
            },
            new ShipmentEntity
            {
                TrackingNumber = "TRK-1004",
                Origin = "Miami, FL",
                Destination = "Atlanta, GA",
                Status = (int)ShipmentStatus.OutForDelivery,
                ShippedDate = now.AddDays(-2),
                EstimatedDelivery = now,
                RecipientName = "David Lee",
                Description = "Clothing – 1 box"
            },
            new ShipmentEntity
            {
                TrackingNumber = "TRK-1005",
                Origin = "Boston, MA",
                Destination = "Philadelphia, PA",
                Status = (int)ShipmentStatus.Delayed,
                ShippedDate = now.AddDays(-5),
                EstimatedDelivery = now.AddDays(1),
                RecipientName = "Eve Martinez",
                Description = "Medical supplies – 2 containers"
            }
        );
        await db.SaveChangesAsync();
    }
}

