@page "/"

@inject IShipmentService ShipmentService
@inject NavigationManager Nav

<PageTitle>ShipmentTracker – Home</PageTitle>

<div class="text-center my-5">
    <h1 class="display-4">📦 Shipment Tracker</h1>
    <p class="lead text-muted">Track your shipment in real time. Enter your tracking number below.</p>
</div>

<div class="row justify-content-center">
    <div class="col-md-6">
        <div class="input-group input-group-lg">
            <input type="text" class="form-control" placeholder="e.g. TRK-1001"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="LookupShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>

        @if (notFound)
        {
            <div class="alert alert-warning mt-3">No shipment found for "<strong>@searchedNumber</strong>".</div>
        }

        @if (shipment is not null)
        {
            <div class="card mt-4">
                <div class="card-body">
                    <h5 class="card-title">@shipment.TrackingNumber</h5>
                    <span class="badge bg-@GetStatusColor(shipment.Status) mb-2">@shipment.Status</span>
                    <p class="mb-1"><strong>From:</strong> @shipment.Origin</p>
                    <p class="mb-1"><strong>To:</strong> @shipment.Destination</p>
                    <p class="mb-1"><strong>Recipient:</strong> @shipment.RecipientName</p>
                    <p class="mb-1"><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMM dd, yyyy")</p>
                    <p class="mb-0"><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                </div>
            </div>
        }
    </div>
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? shipment;
    private bool notFound;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await LookupShipment();
    }

    private async Task LookupShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        notFound = false;
        shipment = null;
        searchedNumber = trackingNumber.Trim();

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
            notFound = shipment is null;
        }
        catch
        {
            notFound = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

