 @page "/track"
 @page "/track/{TrackingNumber}"

 @inject IShipmentService ShipmentService

 <PageTitle>Track Shipment</PageTitle>

 <h2 class="mb-4">🔍 Track a Shipment</h2>

 <div class="row">
     <div class="col-md-6">
         <div class="input-group">
             <input type="text" class="form-control" placeholder="Enter tracking number"
                    @bind="inputTrackingNumber" @bind:event="oninput"
                    @onkeydown="HandleKeyDown" />
             <button class="btn btn-primary" @onclick="Search" disabled="@isLoading">
                 @if (isLoading)
                 {
                     <span class="spinner-border spinner-border-sm me-1"></span>
                 }
                 Search
             </button>
         </div>
     </div>
 </div>

 @if (notFound)
 {
     <div class="alert alert-warning mt-4">No shipment found for "<strong>@searchedNumber</strong>".</div>
 }

 @if (shipment is not null)
 {
     <div class="card mt-4">
         <div class="card-header d-flex justify-content-between align-items-center">
             <strong>@shipment.TrackingNumber</strong>
             <span class="badge bg-@GetStatusColor(shipment.Status) fs-6">@shipment.Status</span>
         </div>
         <div class="card-body">
             <div class="row">
                 <div class="col-md-6">
                     <p><strong>Description:</strong> @shipment.Description</p>
                     <p><strong>Recipient:</strong> @shipment.RecipientName</p>
                 </div>
                 <div class="col-md-6">
                     <p><strong>Origin:</strong> @shipment.Origin</p>
                     <p><strong>Destination:</strong> @shipment.Destination</p>
                 </div>
             </div>
             <hr />
             <div class="row">
                 <div class="col-md-6">
                     <p><strong>Shipped Date:</strong> @shipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                 </div>
                 <div class="col-md-6">
                     <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</p>
                 </div>
             </div>
         </div>
     </div>
 }

 @code {
     [Parameter] public string? TrackingNumber { get; set; }

     private string inputTrackingNumber = string.Empty;
     private string searchedNumber = string.Empty;
     private Shipment? shipment;
     private bool notFound;
     private bool isLoading;

     protected override async Task OnParametersSetAsync()
     {
         if (!string.IsNullOrWhiteSpace(TrackingNumber))
         {
             inputTrackingNumber = TrackingNumber;
             await Search();
         }
     }

     private async Task HandleKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
             await Search();
     }

     private async Task Search()
     {
         if (string.IsNullOrWhiteSpace(inputTrackingNumber)) return;

         isLoading = true;
         notFound = false;
         shipment = null;
         searchedNumber = inputTrackingNumber.Trim();

         try
         {
             shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
             notFound = shipment is null;
         }
         catch
         {
             notFound = true;
         }
         finally
         {
             isLoading = false;
         }
     }

     private static string GetStatusColor(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "secondary",
         ShipmentStatus.PickedUp => "info",
         ShipmentStatus.InTransit => "primary",
         ShipmentStatus.OutForDelivery => "warning",
         ShipmentStatus.Delivered => "success",
         ShipmentStatus.Delayed => "danger",
         _ => "secondary"
     };
 }
